import React, { useState } from 'react';

function CreateEventForm({ onCreateEvent }) {
  const [form, setForm] = useState({
    name: '',
    description: '',
    total_seats: '',
    date: '',
  });
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name.trim()) { setError('Event name is required.'); return; }
    if (!form.total_seats || parseInt(form.total_seats) <= 0) { setError('Total seats must be a positive number.'); return; }
    if (!form.date) { setError('Event date is required.'); return; }

    onCreateEvent({
      name: form.name.trim(),
      description: form.description.trim() || null,
      total_seats: parseInt(form.total_seats),
      date: new Date(form.date).toISOString(),
    });

    setForm({ name: '', description: '', total_seats: '', date: '' });
  };

  return (
    <div style={{ marginTop: '30px', padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
      <h2>Create New Event</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <form onSubmit={handleSubmit}>
        <table>
          <tbody>
            <tr>
              <td><label>Event Name *</label></td>
              <td>
                <input name="name" value={form.name} onChange={handleChange}
                  placeholder="Event name" style={{ padding: '6px', width: '250px' }} />
              </td>
            </tr>
            <tr>
              <td><label>Description</label></td>
              <td>
                <textarea name="description" value={form.description} onChange={handleChange}
                  placeholder="Optional description" rows="3"
                  style={{ padding: '6px', width: '250px' }} />
              </td>
            </tr>
            <tr>
              <td><label>Total Seats *</label></td>
              <td>
                <input type="number" name="total_seats" value={form.total_seats}
                  onChange={handleChange} min="1" placeholder="e.g. 50"
                  style={{ padding: '6px', width: '250px' }} />
              </td>
            </tr>
            <tr>
              <td><label>Event Date *</label></td>
              <td>
                <input type="datetime-local" name="date" value={form.date}
                  onChange={handleChange} style={{ padding: '6px', width: '250px' }} />
              </td>
            </tr>
            <tr>
              <td></td>
              <td>
                <button type="submit" style={{
                  marginTop: '10px', padding: '8px 20px',
                  backgroundColor: '#2196F3', color: 'white', border: 'none', cursor: 'pointer'
                }}>
                  Create Event
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </form>
    </div>
  );
}

export default CreateEventForm;
